import{_ as i,c as t,o,ag as e,j as r}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"インストール","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/installation.md","filePath":"ja/guide/installation.md","lastUpdated":1794112334000}'),l={name:"ja/guide/installation.md"};function n(s,a,h,c,d,p){return o(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h1><h2 id="nicasa-のダウンロード" tabindex="-1">Nicasa のダウンロード <a class="header-anchor" href="#nicasa-のダウンロード" aria-label="Permalink to &quot;Nicasa のダウンロード&quot;">​</a></h2><p>Nicasa は Mac App Store を通じて macOS 版のみ提供されています。アプリは $4.99 の買い切りで、すべての機能を利用できます。</p><h3 id="ダウンロード方法" tabindex="-1">ダウンロード方法 <a class="header-anchor" href="#ダウンロード方法" aria-label="Permalink to &quot;ダウンロード方法&quot;">​</a></h3><ul><li><strong>Mac App Store</strong>：<a href="https://apps.apple.com/us/app/nicasa-image-viewer/id6756032669?mt=12" target="_blank" rel="noreferrer">Nicasa をダウンロード</a> —— $4.99</li><li><strong>Chrome 拡張機能</strong>：<a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">無料 Chrome 拡張機能</a> —— 無料</li></ul><h2 id="インストール手順" tabindex="-1">インストール手順 <a class="header-anchor" href="#インストール手順" aria-label="Permalink to &quot;インストール手順&quot;">​</a></h2><h3 id="mac-app-store-からのインストール" tabindex="-1">Mac App Store からのインストール <a class="header-anchor" href="#mac-app-store-からのインストール" aria-label="Permalink to &quot;Mac App Store からのインストール&quot;">​</a></h3><ol><li>上記の「Nicasa をダウンロード」リンクをクリックするか、Mac App Store で「Nicasa」を検索します</li><li>「入手」または「購入」をクリックして購入します（$4.99）</li><li>アプリが自動的にダウンロード・インストールされます</li><li>アプリケーションフォルダまたは Launchpad から Nicasa を起動します</li></ol><h3 id="chrome-拡張機能のインストール" tabindex="-1">Chrome 拡張機能のインストール <a class="header-anchor" href="#chrome-拡張機能のインストール" aria-label="Permalink to &quot;Chrome 拡張機能のインストール&quot;">​</a></h3><ol><li><a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">Chrome ウェブストアのページ</a>にアクセスします</li><li>「Chrome に追加」をクリックします</li><li>ポップアップでインストールを確認します</li><li>拡張機能がブラウザに追加されます</li></ol><h4 id="chrome-拡張機能のデモ" tabindex="-1">Chrome 拡張機能のデモ <a class="header-anchor" href="#chrome-拡張機能のデモ" aria-label="Permalink to &quot;Chrome 拡張機能のデモ&quot;">​</a></h4>',11),r("div",{style:{position:"relative","padding-bottom":"56.25%",height:"0"}},[r("iframe",{src:"https://www.youtube.com/embed/NJPweIr1J4s",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:"",style:{position:"absolute",top:"0",left:"0",width:"100%",height:"100%"}})],-1),e('<p><a href="https://www.youtube.com/watch?v=NJPweIr1J4s" target="_blank" rel="noopener">視聴：Nicasa Chrome 拡張機能のクイックデモ</a></p><h2 id="初回起動" tabindex="-1">初回起動 <a class="header-anchor" href="#初回起動" aria-label="Permalink to &quot;初回起動&quot;">​</a></h2><p>Nicasa を初めて起動したとき：</p><ol><li>必要な権限の付与を求められます（スクリーンショットには画面収録の権限が必要です）</li><li>アプリが「ピクチャ」フォルダ内の画像をスキャンします</li><li>すぐにコレクションの閲覧を開始できます</li><li>ウェブ閲覧を強化するため、Chrome 拡張機能のインストールもご検討ください</li></ol><h3 id="finder-同期拡張機能" tabindex="-1">Finder 同期拡張機能 <a class="header-anchor" href="#finder-同期拡張機能" aria-label="Permalink to &quot;Finder 同期拡張機能&quot;">​</a></h3><p>Nicasa には画像を素早く処理するための Finder ツールバー拡張機能が含まれています：</p><ol><li>Nicasa を起動したら、<strong>システム設定</strong> → <strong>機能拡張</strong> → <strong>Finder 機能拡張</strong> を開きます</li><li><strong>Nicasa Finder Sync</strong> を有効にします</li><li>Finder のツールバーを右クリック → <strong>ツールバーをカスタマイズ…</strong></li><li>Nicasa のボタンをツールバーにドラッグします</li></ol><p>これにより、Finder から直接選択した画像を最適化・編集できます。</p><h2 id="システム要件" tabindex="-1">システム要件 <a class="header-anchor" href="#システム要件" aria-label="Permalink to &quot;システム要件&quot;">​</a></h2><ul><li><strong>macOS</strong>：10.13 以降</li><li><strong>ストレージ</strong>：54.5 MB の空き容量</li><li><strong>メモリ</strong>：最低 4GB RAM、8GB 推奨</li></ul><h2 id="権限" tabindex="-1">権限 <a class="header-anchor" href="#権限" aria-label="Permalink to &quot;権限&quot;">​</a></h2><p>Nicasa は以下の権限を必要とします：</p><ul><li><strong>画面収録</strong>：スクリーンショット機能に使用（後から許可できます）</li><li><strong>アクセシビリティ</strong>：オーバーレイモードの機能に使用（任意）</li><li><strong>ファイルとフォルダ</strong>：「ピクチャ」フォルダおよびユーザーが選択したディレクトリへのアクセス</li></ul><p>これらの権限は「システム設定 &gt; プライバシーとセキュリティ」でいつでも変更できます。</p><h2 id="インストールのトラブルシューティング" tabindex="-1">インストールのトラブルシューティング <a class="header-anchor" href="#インストールのトラブルシューティング" aria-label="Permalink to &quot;インストールのトラブルシューティング&quot;">​</a></h2><p>インストール中に問題が発生した場合：</p><ul><li>管理者（root）権限があることを確認してください</li><li>システムが最低要件を満たしているか確認してください</li><li>ファイルを再ダウンロードしてみてください</li><li>Linux の場合は、必要な依存関係がインストールされているか確認してください</li></ul><p>さらにサポートが必要な場合は、<a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">Issues ページ</a>をご覧ください。</p>',18)])])}const g=i(l,[["render",n]]);export{u as __pageData,g as default};
